(() => {
  const rows = [...document.querySelectorAll('.infobox tr')]
    .filter(r => /height/i.test(r.innerText))
    .map(r => r.innerText.replace(/\s+/g, ' ').trim());
  const lead = [...document.querySelectorAll('#mw-content-text .mw-parser-output > p')]
    .map(p => p.innerText)
    .filter(t => /tall|height|metres/i.test(t))
    .slice(0, 2);
  return JSON.stringify({ title: document.title, rows, lead }, null, 2);
})()

