input.script:
const rows = [...document.querySelectorAll('.infobox tr')].map(r => r.textContent.replace(/\s+/g, ' ').trim());
const i = rows.findIndex(r => /^Record height/i.test(r));
const j = rows.findIndex(r => /^Height$/i.test(r));
const paras = [...document.querySelectorAll('#mw-content-text p')].map(p => p.textContent.replace(/\s+/g, ' ').trim()).filter(t => /\btall\b|metres/i.test(t)).slice(0, 3);
return JSON.stringify({ record: rows.slice(i, i + 4), height: rows.slice(j, j + 6), paras }, null, 2);

